import{_ as a,a0 as l,w as n,s as p,ao as F,I as s,x as t,a1 as o,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"WiFi 6 帶來的不僅是高速 | LCTT x X-CMD","titleTemplate":false,"description":"WiFi 6 帶來的不僅是高速 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"WiFi 6 帶來的不僅是高速 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"WiFi 6 帶來的不僅是高速 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20220608 WiFi 6 Promises Much More than Faster Speeds","title":"WiFi 6 帶來的不僅是高速","tag":"202212","desc":""},"relativePath":"202212/20220608 WiFi 6 Promises Much More than Faster Speeds.md","filePath":"[post].md"}'),u={name:"202212/20220608 WiFi 6 Promises Much More than Faster Speeds.md"};function W(m,i,d,f,h,g){const e=l("Link");return n(),p("div",null,[i[15]||(i[15]=F('<h1 id="wifi-6-帶來的不僅是高速" tabindex="-1">WiFi 6 帶來的不僅是高速 <a class="header-anchor" href="#wifi-6-帶來的不僅是高速" aria-label="Permalink to “WiFi 6 帶來的不僅是高速”">​</a></h1><blockquote><p>WiFi 6 提高了網絡連通性，它在不久的將來有望為數萬億台設備組網，並且能夠不間斷而高效地工作。它雖然在 2019 年就取得了官方認證，但由於疫情原因，它的測試工作面臨不少挑戰。本文旨在對這項技術進行概述。</p></blockquote><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/05/WiFi-6.jpg" alt="WiFi-6"></p><p>WiFi 技術的下一代標準，稱為 “WiFi 6”，也可以稱為 “AX WiFi” 或 “802.11ax”。它是為滿足指數級增長的設備組網需求而產生的，因此也可以用於 VR 和智能家居。它是現有的 802.11ac WiFi 標準的升級版，可以應對現有技術在容量、效率、覆蓋範圍和性能方面遇到的挑戰。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/05/WiFi-6-1.jpg" alt="Figure 1: WiFi 6"></p><p>這項技術是在 2014 年進行研發，完成於 2018 年，由 IEEE 高性能無線網絡研究組（HEW SG）發佈。產品認證於 2019 年後期進行，此時三星 Galaxy Note 10 和 Ruckus R750 使用了這種技術。WiFi 6 運行於 1GHz 和 6GHz 波段，主要的頻率為 2.4GHz-5GHz。</p><p>如今，每個家庭平均有九台設備需要連接 WiFi。WiFi 6 主要致力於改善網絡質量，而不是提升某些設備的速度。</p><h3 id="wifi-6的特點" tabindex="-1">WiFi 6的特點 <a class="header-anchor" href="#wifi-6的特點" aria-label="Permalink to “WiFi 6的特點”">​</a></h3><ul><li><strong>多用户、多輸入、多輸出（MU-MIMO）：</strong> 路由器和多台設備可以同時通信。在 2.4GHz 和 5GHz 頻率上，它支持四個同步的數據流，當這些數據流添加到一個用户時，可以從智能路由器接收到相當大的輸入數據的帶寬。</li><li><strong>1024-QAM:</strong> 這令 WiFi 6 的每個數據包能編碼的字節數更多，吞吐量增加了 25%。它不僅提高了大業務量情況下的通信效率，也最大限度增加了傳輸速率。這在現代企業應用系統領域有很大的優勢。</li><li><strong>正交頻分複用（OFDM）：</strong> 支持四倍的副載波，速度也提高了 11%。擴展的信號支持用户同時進行更多數據包傳輸。所以數據包之間的等待時間和延遲就減少了。</li><li><strong>增加的信道寬度：</strong> 80MHz 的波段加入了 160MHz 的信道通信，信道寬度增加了一倍。因此，路由器可以容納更多用户，為每個用户提供更大的數據流。</li><li><strong>目標喚醒時間（TWT）：</strong> 這是 WiFi 6 特有的。它支持每台設備獨立協商發送和接收的喚醒時間。它可以增加總體睡眠時間，令電池壽命最大化。它還支持許多額外的網絡選項，特別是對 IoT 設備的支持。</li><li><strong>提升安全性：</strong> 一切支持 WiFi 6 的設備都需要包含 WPA3 協議。它可以對未經驗證的通信進行加密，針對暴力字典攻擊提供了強大的密碼保護，以及對敏感信息進行 192 位的加密，提升數據的可靠性。</li><li><strong>波束賦形：</strong> 藉助八根天線，波束賦形能提高傳輸速率，通信範圍也因直接定向到某個客户端而擴大。它對快速移動的、可能面臨多用户、多輸入、多輸出的設備起到了支撐作用。波束賦形也有利於控制那些蓄意發出干擾信號的天線的傳輸。然後信號會被重新定向到新的目標。</li></ul><h3 id="支持-wifi-6-的設備" tabindex="-1">支持 WiFi 6 的設備 <a class="header-anchor" href="#支持-wifi-6-的設備" aria-label="Permalink to “支持 WiFi 6 的設備”">​</a></h3><p>到目前為止，路由器、中繼器、網狀網絡和多數 WiFi 使用者還是以 WiFi 5 為標準。WiFi 6 是 2019 年推出的。一些支持 WiFi 5 的早期設備存在一些兼容性問題 —— 它們可以使用 WiFi 6 的網絡，但得不到相應的支持服務。</p><p>WiFi 6 的路由器是向後兼容的。應該確保網絡已經為此做好了準備。</p><p>WiFi 6 實現了較低的電量消耗，在任何場景（包括 IoT）下，都是個不錯的選擇。它減少了不必要的數據流動，還會通知設備何時將數據激活或令其睡眠。所以不必要的數據流動減少了，性能和電池壽命也提高了。</p><p>三星 Galaxy Note 10 和 Ruckus R750 是全球第一款經認證支持 WiFi 6 的智能手機和接入設備，蘋果的最新款 iPhone 也緊隨其後。WiFi 聯盟已經確立了認證方案，正如人們預期的那樣，等待入市的那些新款無線產品也開始申請認證了。下列設備已支持 WiFi 6:</p><ul><li>iPhone 11 和之後的型號</li><li>三星 Galaxy S10、S20、Note 10 和 Note 20</li><li>配置 M1 處理器的蘋果電腦</li><li>智能電視</li></ul><blockquote><p>為了全面享受到 802.11ax 標準帶來的改進，硬件和軟件的功能都需要基於這種 WiFi 技術進行升級。</p></blockquote><h3 id="硬件測試" tabindex="-1">硬件測試 <a class="header-anchor" href="#硬件測試" aria-label="Permalink to “硬件測試”">​</a></h3><p>為了充分挖掘最新款設備的潛力，需要一台 WiFi 6 路由器來運行網絡。幾年前，這麼做的成本很高，但現在我們有多種選擇，甚至可以使用網格系統、遊戲路由器、範圍擴展器等等。只有在進行實際測試時，才可以購買最划算的設備。如今，在速度方面，TP-Link Archer AX6000 是最快的，它擊敗了所有的競爭者。這款路由器可以以 1523 Mbps 的速率無線傳輸數據，有效傳輸距離為 1.5米（5 英尺）。</p><p>很重要的一點，請務必記住，這些路由器提速，並不是在變魔術。理論上的最大速率 9.6 Gbps是實現不了的。這種理論上的最大速率，實際上也會被多台設備分攤掉。</p><p>WiFi 6 側重於在連接設備密集的地方提供高質量的連接。它不會令單台設備的速率指數級增長，但會使相關的設備運行處於理想水平。</p><p>只有各大互聯網服務提供商（ISP）的加速計劃與 WiFi 6 路由器結合起來，才能體現它的真正潛力。真正的挑戰是那些 ISP 承受的，因為它們需要鋪設新型的光纖來利用這種下一代技術。存在一個重要的問題：當ISP 的通信速率變得更快，現有的硬件會變得多餘嗎？</p><h3 id="wifi-6-的應用" tabindex="-1">WiFi 6 的應用 <a class="header-anchor" href="#wifi-6-的應用" aria-label="Permalink to “WiFi 6 的應用”">​</a></h3><ul><li><strong>大型公共場所（LPV）：</strong> 體育館和會議中心是上千台設備同時聯網的公共場所。WiFi 6 能改善參會者體驗，增強消費者互動，還能提供附加服務，比如即時回放，訂購餐食等。它還支持 LPV 業主開拓新的商業機會。</li><li><strong>交通樞紐：</strong> 公共交通站點也是人們需要同時聯網的場所。OFDMA 和 BSS 這類明顯具有 WiFi 6 色彩的技術為解決這種問題提供了必要的工具。</li><li><strong>物聯網和智慧城市建設：</strong> WiFi 6 的能效令物聯網設備可以進入休眠模式，並且可以在預定的間隔內開啓信號發射器，以便在無需過多維護的情況下增加現場作業時間。</li><li><strong>教育機構：</strong> 大學校園內的圖書館、禮堂和報告廳內的日間 WiFi 使用密度是最高的，夜晚幾乎沒有人。WiFi 6 是這類場景的完美選項。</li></ul><p>（LCTT 譯註：相關產品推薦部分節略。）</p><h3 id="面臨的挑戰" tabindex="-1">面臨的挑戰 <a class="header-anchor" href="#面臨的挑戰" aria-label="Permalink to “面臨的挑戰”">​</a></h3><p>WiFi 6 不一定使速度更快，但它能確保在一定範圍內的設備速率不會在未來幾年變慢。雖然它面臨三重挑戰，但這些問題常常被忽視。</p><ul><li>需要對不支持的設備進行升級：即使 Wifi 6 向後兼容，但只能在最大限度使用這種技術時才能做得合理。這意味着每次都要更新設備。</li><li>內部網絡以外的速度和性能：WiFi 6 能為諸如雲文件共享之類服務提供極好的連接性。然而，ISP 的相關資源也會影響速度和性能。</li><li>覆蓋範圍問題：在各個國家，傳輸信號和帶寬都是由法律規定上限的。因此，為了符合法律規定的上限，WiFi 6 的覆蓋範圍也是受限的。</li></ul><p>儘管存在這些挑戰，一些企業，像 Aruba、華碩、AT&amp;T、Boingo、博通、思科、Comcast、CommScope、Cypress、Extreme Networks、英特爾、Netgear、Orange、高通、TP-Link 和小米，都在關注 WiFi 6 更多的可能性。</p><hr>',29)),s("p",null,[i[1]||(i[1]=t("via: ",-1)),o(e,{href:"https://www.opensourceforu.com/2022/06/wifi-6-promises-much-more-than-faster-speeds/"},{default:r(()=>[...i[0]||(i[0]=[t("https://www.opensourceforu.com/2022/06/wifi-6-promises-much-more-than-faster-speeds/",-1)])]),_:1})]),s("p",null,[i[6]||(i[6]=t("作者：",-1)),o(e,{href:"https://www.opensourceforu.com/author/sharon-katta/"},{default:r(()=>[...i[2]||(i[2]=[t("Sharon Katta",-1)])]),_:1}),i[7]||(i[7]=t(" 選題：",-1)),o(e,{href:"https://github.com/lkxed"},{default:r(()=>[...i[3]||(i[3]=[t("lkxed",-1)])]),_:1}),i[8]||(i[8]=t(" 譯者：",-1)),o(e,{href:"https://github.com/cool-summer-021"},{default:r(()=>[...i[4]||(i[4]=[t("cool-summer-021",-1)])]),_:1}),i[9]||(i[9]=t(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:r(()=>[...i[5]||(i[5]=[t("wxy",-1)])]),_:1})]),s("p",null,[i[12]||(i[12]=t("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...i[10]||(i[10]=[t("LCTT",-1)])]),_:1}),i[13]||(i[13]=t(" 原創編譯，",-1)),o(e,{href:"https://linux.cn/"},{default:r(()=>[...i[11]||(i[11]=[t("Linux中國",-1)])]),_:1}),i[14]||(i[14]=t(" 榮譽推出",-1))])])}const P=a(u,[["render",W]]);export{x as __pageData,P as default};
